OPERATING_MODEL_SQLITE_SCHEMA=r'''
CREATE TABLE operating_models(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,version INTEGER NOT NULL,compiler_version INTEGER NOT NULL,answers_hash TEXT NOT NULL,model_json TEXT NOT NULL,diff_json TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('preview','approved','retired')),created_by TEXT NOT NULL,created_at TEXT NOT NULL,approved_by TEXT,approved_at TEXT,UNIQUE(workspace_id,version));
CREATE TABLE role_assignments(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,user_id TEXT NOT NULL,role_name TEXT NOT NULL,location_id TEXT,company_id TEXT,limits_json TEXT NOT NULL,template_version INTEGER NOT NULL,effective_from TEXT NOT NULL,effective_to TEXT,assigned_by TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE approval_requests(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,action TEXT NOT NULL,record_type TEXT NOT NULL,record_id TEXT NOT NULL,amount_minor INTEGER,location_id TEXT,status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected')),requested_by TEXT NOT NULL,decided_by TEXT,requested_at TEXT NOT NULL,decided_at TEXT);
'''
